<?php $title="Add Customer";require "includes/header.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO customers(name,email,phone,city,segment) VALUES(?,?,?,?,?)");$s->bind_param("sssss",$_POST["name"],$_POST["email"],$_POST["phone"],$_POST["city"],$_POST["segment"]);$s->execute();go("customers.php");}?><div class="card"><h2>New Customer</h2><form method="post"><label>Name</label><input name="name" required><label>Email</label><input name="email" type="email"><label>Phone</label><input name="phone"><label>City</label><input name="city"><label>AI Segment</label><select name="segment"><option>New Rider</option><option>Adventure</option><option>Commuter</option><option>Premium</option><option>Family</option></select><button class="btn primary">Save Customer</button></form></div><?php require "includes/footer.php";?>